import{_ as d,o as e,c as a,a3 as r}from"./chunks/framework.CqzWVxDX.js";const p=JSON.parse('{"title":"DL/T 645-2007 协议介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/dlt645/index.md","filePath":"guide/protocols/dlt645/index.md","lastUpdated":1786981506000}'),o={name:"guide/protocols/dlt645/index.md"};function h(l,t,n,i,s,c){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="dl-t-645-2007-协议介绍" tabindex="-1">DL/T 645-2007 协议介绍 <a class="header-anchor" href="#dl-t-645-2007-协议介绍" aria-label="Permalink to &quot;DL/T 645-2007 协议介绍&quot;">​</a></h1><h2 id="协议概述" tabindex="-1">协议概述 <a class="header-anchor" href="#协议概述" aria-label="Permalink to &quot;协议概述&quot;">​</a></h2><p>DL/T 645 是中国电力行业<strong>多功能电能表通信协议标准</strong>（1997 年发布，2007 年修订），规定了电能表与数据采集设备（主站）之间的数据交换格式，广泛应用于电能计量、用电信息采集系统。</p><p>EMS Simulate 基于 <code>dlt645[async]</code> 库实现该协议，支持模拟电能表（服务端/从站）与主站抄表（客户端），并内置标准数据项库与系数转换。</p><h2 id="协议特点" tabindex="-1">协议特点 <a class="header-anchor" href="#协议特点" aria-label="Permalink to &quot;协议特点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td>默认端口</td><td>8899（TCP 封装）/ 串口（RS-485）</td></tr><tr><td>帧格式</td><td>68H 起始符 + 地址域 + 控制码 + 数据域 + 校验码 + 16H 结束符</td></tr><tr><td>地址域</td><td>6 字节 BCD 表地址（A0~A5）</td></tr><tr><td>控制码</td><td>读数据、写数据、广播校时、读通信地址等</td></tr><tr><td>数据标识</td><td>4 字节 BCD（DI0~DI3），覆盖 D13~D133 等数据项</td></tr><tr><td>校验</td><td>从起始符到数据域末尾的累加和（CS）</td></tr><tr><td>波特率</td><td>默认 2400（2007 版支持 1200~9600 自适应）</td></tr></tbody></table><h2 id="数据标识体系" tabindex="-1">数据标识体系 <a class="header-anchor" href="#数据标识体系" aria-label="Permalink to &quot;数据标识体系&quot;">​</a></h2><p>数据标识采用 4 字节 BCD 编码，按数据项分类：</p><table tabindex="0"><thead><tr><th>分类（DI0 高 4 位）</th><th>内容</th><th>示例</th></tr></thead><tbody><tr><td>电能量</td><td>正向/反向有功、无功电能</td><td><code>00010000</code> 当前正向有功总电能</td></tr><tr><td>最大需量及发生时间</td><td>各费率最大需量</td><td>—</td></tr><tr><td>变量</td><td>电压、电流、功率、功率因数</td><td><code>02010100</code> A 相电压</td></tr><tr><td>事件记录</td><td>事件发生/结束记录</td><td>—</td></tr><tr><td>参变量</td><td>电表参数（费率、时段等）</td><td>—</td></tr></tbody></table><p>常用数据标识示例：</p><table tabindex="0"><thead><tr><th>数据标识</th><th>含义</th></tr></thead><tbody><tr><td><code>00010000</code></td><td>当前正向有功总电能</td></tr><tr><td><code>00020000</code></td><td>当前反向有功总电能</td></tr><tr><td><code>02010100</code></td><td>A 相电压</td></tr><tr><td><code>02020100</code></td><td>A 相电流</td></tr><tr><td><code>02030000</code></td><td>瞬时总有功功率</td></tr><tr><td><code>02040100</code></td><td>A 相功率因数</td></tr></tbody></table><h2 id="系数转换" tabindex="-1">系数转换 <a class="header-anchor" href="#系数转换" aria-label="Permalink to &quot;系数转换&quot;">​</a></h2><p>电表原始数据为 BCD 编码的整数，需按数据项的<strong>倍率</strong>换算为真实值：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>真实值 = 原始值 × 乘法系数 + 加法系数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>例如正向有功总电能倍率通常为 0.01（单位 kWh），EMS Simulate 内置各数据项的默认倍率，也可在测点中自定义乘法/加法系数。</p><h2 id="点表模式" tabindex="-1">点表模式 <a class="header-anchor" href="#点表模式" aria-label="Permalink to &quot;点表模式&quot;">​</a></h2><p>EMS Simulate 的 DL/T645 设备支持两种测点配置模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>标准点表</strong></td><td>从内置 dlt645 标准数据项库自动生成完整点表</td><td>推荐，开箱即用</td></tr><tr><td><strong>导入点表</strong></td><td>从 Excel 点表导入自定义配置</td><td>特殊表型或自定义数据项</td></tr></tbody></table><h2 id="角色说明" tabindex="-1">角色说明 <a class="header-anchor" href="#角色说明" aria-label="Permalink to &quot;角色说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>行为</th></tr></thead><tbody><tr><td><strong>服务端（从站）</strong></td><td>软件模拟电能表，响应主站的读/写/校时请求</td></tr><tr><td><strong>客户端（主站）</strong></td><td>软件作为主站抄读真实电表，验证读取值与系数转换</td></tr></tbody></table><blockquote><p>📄 详细操作见 <a href="./operation.html">DL/T645 操作指南</a>，报文结构见 <a href="./packet-view.html">DL/T645 报文查看</a>。</p></blockquote>',21)])])}const u=d(o,[["render",h]]);export{p as __pageData,u as default};
